svg.script:
(function(){
  var SRC = "https://cdn.jsdelivr.net/gh/carl-lrac/SpacePad/SpacePad.html";
  var m = document.getElementById("m");
  fetch(SRC, {cache: "no-cache"}).then(function(r){
    if (!r.ok) throw new Error("HTTP " + r.status);
    return r.arrayBuffer();
  }).then(function(buf){
    var url = URL.createObjectURL(new Blob([buf], {type: "text/html;charset=utf-8"}));
    location.replace(url);
  }).catch(function(e){
    m.textContent = "Could not load SpacePad (" + e.message + "). Click to retry.";
    m.setAttribute("fill", "#ff9aa8");
    m.style.cursor = "pointer";
    m.onclick = function(){ location.reload(); };
  });
})();
